import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * Format: invoice number (or DRAFT), customer name, line items, subtotal, discount (if any), VAT (if any), and total.
 * All amounts are formatted as euros using formatEuros().
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate?: number }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const number = invoice.number ?? 'DRAFT';
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown';

  const lines = [];
  lines.push(number);
  lines.push(customerName);

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const formattedUnitPrice = formatEuros(line.unitPrice);
    const formattedLineTotal = formatEuros(lineTotal);
    let lineStr = `${line.qty} × ${line.name} @ ${formattedUnitPrice} = ${formattedLineTotal}`;
    if (line.discountPercent && line.discountPercent > 0) {
      const lineDiscount = Math.round(lineTotal * (line.discountPercent / 100));
      const formattedDiscount = formatEuros(lineDiscount);
      lineStr += ` (${line.discountPercent}% off: -${formattedDiscount})`;
    }
    lines.push(lineStr);
  }

  const totalsResult = invoiceTotals(invoice);
  if (totalsResult.ok) {
    const { subtotal, discount, vat, total } = totalsResult.value;
    const formattedSubtotal = formatEuros(subtotal);
    lines.push(`Subtotal: ${formattedSubtotal}`);
    if (discount > 0) {
      const formattedDiscount = formatEuros(discount);
      lines.push(`Discount: -${formattedDiscount}`);
    }
    if (vat > 0) {
      const formattedVAT = formatEuros(vat);
      lines.push(`VAT: +${formattedVAT}`);
    }
    const formattedTotal = formatEuros(total);
    lines.push(`Total: ${formattedTotal}`);
  } else {
    lines.push('Total: Unable to calculate');
  }

  return lines.join('\n');
}

