    customerId: 'C-002', // standard tier, no tier discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // Should not contain a "Discount:" line when there's no discount, but VAT will be shown
  // DES-HOUR: 8500, VAT: 8500 * 21% = 1785, Total: 10285
