test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = {
    ...invoice,
    voucher: { code: 'DISCOUNT', amount: 1000 },
  };

  const text = renderInvoiceText(withVoucher);
  const lines = text.split('\n');
  // Should have voucher line before total
  assert.match(lines[3], /^Discount:/);
  assert.match(lines[4], /^VAT:/);
  assert.match(lines[5], /^Voucher: -€10\.00/);
  assert.equal(lines[6], 'Total: €102.85');
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withDueDate = {
    ...invoice,
    dueDate: '2026-11-07',
  };

  const text = renderInvoiceText(withDueDate);
  const lines = text.split('\n');
  assert.equal(lines[lines.length - 1], 'Due: 2026-11-07');
});

test('renderInvoiceText does not show due date when absent', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const withPayment = {
    ...issued,
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };

  const text = renderInvoiceText(withPayment);
  const lines = text.split('\n');
  assert.match(lines[lines.length - 1], /^Paid: €50\.00/);
});

test('renderInvoiceText shows multiple payments as single paid line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const withPayments = {
    ...issued,
    payments: [
      { amount: 5000, date: '2026-10-15' },
      { amount: 4771, date: '2026-10-20' },
    ],
  };

  const text = renderInvoiceText(withPayments);
  const lines = text.split('\n');
  // Total paid should be 50 + 47.71 = 97.71
