test('renderInvoiceText with various quantities and prices', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier, no tier discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'ICON-SET', qty: 100 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // DES-HOUR: 5 × €85.00 = €425.00, no bulk discount, VAT: €89.25
  // ICON-SET: 100 × €9.80 = €980.00, bulk discount: €24.50, after: €955.50, VAT: €200.66
  // Subtotal: €1,405.00
  // Discount: €24.50
  // VAT: €289.91
  // Total: €1,670.41
  assert.match(lines[2], /^5 × Design work \(hour\) @ €85\.00 = €425\.00$/);
  assert.match(lines[3], /^100 × Icon set \(24 icons\) @ €9\.80 = €980\.00$/);
  assert.equal(lines[4], 'Subtotal: €1,405.00');
  assert.equal(lines[5], 'Discount: -€24.50');
  assert.equal(lines[6], 'VAT: +€289.91');
  assert.equal(lines[7], 'Total: €1,670.41');
});

