test('renderInvoiceText shows voucher, due, and paid together', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const complete = {
    ...issued,
    dueDate: '2026-11-07',
    voucher: { code: 'LOYALTY', amount: 500 },
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };

  const text = renderInvoiceText(complete);
  const lines = text.split('\n');
  // Check structure: [..., Subtotal, Discount, VAT, Voucher, Total, Due, Paid]
  const lastFour = lines.slice(-4);
  assert.match(lastFour[0], /^Voucher: -€5\.00/);
  assert.match(lastFour[1], /^Total:/);
  assert.equal(lastFour[2], 'Due: 2026-11-07');
  assert.equal(lastFour[3], 'Paid: €50.00');
});

